CREATE TABLE staff_registry (staff_identity_id BIGINT UNSIGNED PRIMARY KEY, status VARCHAR(30) NOT NULL DEFAULT 'PRE_VERIFIED', verified_by BIGINT UNSIGNED NOT NULL, verified_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(staff_identity_id) REFERENCES staff_identities(id), FOREIGN KEY(verified_by) REFERENCES users(id), CHECK(status IN ('PRE_VERIFIED','CLAIMED','INACTIVE'))) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
